// Image families are finite curated AI illustrations, not per-birth generation.
// Appearance RNG is independent of simulation RNG to preserve old saves.
export const LOOKS=[
{id:'gold',label:'황갈색 · 흰 가슴 · 늘어진 귀',coat:'황갈색',ears:'늘어진 귀',type:'단모 믹스',atlas:'life-atlas-a.png',row:0},
{id:'black-white',label:'검정·흰색 · 흰 콧등 · 선 귀',coat:'검정·흰색',ears:'선 귀',type:'단모 믹스',atlas:'life-atlas-a.png',row:1},
{id:'chocolate',label:'초콜릿색 · 흰 턱 · 늘어진 귀',coat:'초콜릿색',ears:'늘어진 귀',type:'중모 믹스',atlas:'life-atlas-a.png',row:2},
{id:'cream-curly',label:'크림색 · 곱슬털 · 늘어진 귀',coat:'크림색',ears:'늘어진 귀',type:'푸들 타입 믹스',atlas:'life-atlas-b.png',row:0},
{id:'sable',label:'적갈색 · 밝은 볼 · 선 귀',coat:'적갈색',ears:'선 귀',type:'스피츠 타입 믹스',atlas:'life-atlas-b.png',row:1},
{id:'gray-white',label:'회색·흰색 · 얼굴 마스크 · 선 귀',coat:'회색·흰색',ears:'선 귀',type:'허스키 타입 믹스',atlas:'life-atlas-b.png',row:2}];
const breedLook=(id,label,atlas,row)=>({id,label,atlas,row,coat:label,ears:'품종 계열에 따른 귀',type:label});
LOOKS.push(breedLook('jindo','흰색 · 진돗개 타입 믹스','breeds-c.png',0),breedLook('labrador','황색 · 래브라도 타입 믹스','breeds-c.png',1),breedLook('poodle','살구색 곱슬털 · 푸들','breeds-c.png',2),breedLook('shiba','적갈색 · 시바 타입 믹스','breeds-d.png',0),breedLook('pariah','황갈색 · 인디언 파리아 타입','breeds-d.png',1),breedLook('terrier','갈색·흰색 거친 털 · 테리어 믹스','breeds-d.png',2),breedLook('shepherd','검정·황갈색 · 셰퍼드 믹스','breeds-e.png',0),breedLook('small-mix','크림·갈색 긴 털 · 소형 믹스','breeds-e.png',1),breedLook('husky','회색·흰색 · 허스키 믹스','breeds-e.png',2));
export const BREED_IMAGES={'지역 믹스':['gold','black-white','chocolate'],'진돗개 믹스':['jindo'],'푸들':['poodle'],'시바 믹스':['shiba'],'인디언 파리아 타입':['pariah'],'래브라도 믹스':['labrador'],'테리어 믹스':['terrier'],'셰퍼드 믹스':['shepherd'],'소형 믹스':['small-mix'],'허스키 믹스':['husky']};

function hash(seed){let x=(Number(seed)^0x91e10da5)>>>0;x=Math.imul(x^(x>>>16),0x7feb352d);x=Math.imul(x^(x>>>15),0x846ca68b);return (x^(x>>>16))>>>0}
export function initAppearance(s){const allowed=BREED_IMAGES[s.breed];if(!allowed)return;if(s.appearance?.version===2&&s.appearance.breed===s.breed&&allowed.includes(s.appearance.lookId))return;const n=hash(s.seed),lookId=allowed[n%allowed.length];const ranges={'푸들':[4,8],'진돗개 믹스':[15,10],'시바 믹스':[8,7],'래브라도 믹스':[22,12],'허스키 믹스':[18,10],'셰퍼드 믹스':[22,15],'소형 믹스':[4,6],'테리어 믹스':[6,10],'인디언 파리아 타입':[12,10],'지역 믹스':[8,20]};const [base,span]=ranges[s.breed];const kg=base+(hash(n+1)%(span*10))/10;s.appearance={version:2,breed:s.breed,lookId,adultKg:kg,body:kg<10?'작은 체격':kg<25?'중간 체격':'큰 체격',eyeColor:'갈색',nose:'품종 계열에 따른 코색',coatVariation:hash(n+3)%1000};}
export function lookOf(s){initAppearance(s);return BREED_IMAGES[s.breed]?.includes(s.appearance?.lookId)?LOOKS.find(l=>l.id===s.appearance.lookId)||null:null}
export function stageOf(day){return day<20?0:day<365?1:day<2920?2:3}
export function imageFor(s,event=null){const look=lookOf(s);const stage=stageOf(event?.day??s.day);if(!look)return null;const scene=event&&({adopt:0,moving:1,settled:1,'weather-result':2,'gate-out':2,reunion:3,'alone-result':4,'care-change':4,'care-recovery':5,'dog-friend':5,grass:5})[event.id];if(scene!==undefined)return {url:'assets/events-atlas.png',x:(scene%3)*50,y:Math.floor(scene/3)*100,columns:3,rows:2,stage,look:look.id,alt:'강아지의 눈높이에서 바라본 '+['새 가족의 문 앞','이사한 집','낯선 비 오는 길','가족과의 재회','기다리는 집','함께 걷는 공원'][scene]};return {url:`assets/${look.atlas}`,columns:4,rows:3,x:stage*100/3,y:look.row*50,stage,look:look.id,alt:`${look.label} 강아지의 ${['출생','어린 시절','성견','노년'][stage]} 참고 이미지`}}
export const PHOTO_EVENTS=new Set(['birth','newborn','growing-body','birthday','adopt','moving','settled','dog-friend','reunion','aging','care-recovery','death','gate-out','alone-result','weather-result','care-change','grass']);
export function validateAppearance(s){const a=s.appearance;if(a&&(!LOOKS.some(l=>l.id===a.lookId)||!Number.isFinite(a.adultKg)||a.adultKg<=0||typeof a.body!=='string'))throw Error('손상된 외형 기록');}
// Select against the entire chronological history, never just the visible page.
// This keeps each atlas cell to one occurrence even when older entries are loaded.
export function photoLogIndices(s){const seen=new Set(),selected=new Set();for(let i=0;i<s.log.length;i++){const e=s.log[i];if(!PHOTO_EVENTS.has(e.id))continue;const p=imageFor(s,e);if(!p)continue;const key=`${p.url}:${p.x}:${p.y}`;if(seen.has(key))continue;seen.add(key);selected.add(i)}return selected;}

export function atlasFrame(pic){return {width:`${pic.columns*100}%`,height:`${pic.rows*100}%`,left:`${-pic.x*(pic.columns-1)}%`,top:`${-pic.y*(pic.rows-1)}%`}}
// Dashboard selection uses developmental milestones AND current context.
// The old dashboard called imageFor(s) without an event, so scene atlases were unreachable.
export function visualPhase(s,day=s.day){const m=s.milestones||{};return day<(m.eyes??14)?'newborn':day<(m.walking??23)?'eyes-open':day<55?'first-steps':day<(s.reproduction?.matureAt??200)?'puppy':day<365?'adolescent':day<2920?'adult':'senior'}
export const PHASE_NAMES={newborn:'출생 · 눈을 뜨기 전','eyes-open':'눈이 열린 시기','first-steps':'처음 걷는 시기',puppy:'유년기',adolescent:'청소년기',adult:'성체',senior:'노년기'};
const SCENE_IDS={'clinical-symptom':4,'clinical-diagnosis':4,'surgery-performed':4,'clinical-managed':5,'rescued-shelter':0,'guardian-changed':1,'shop-arrival':1,adopt:0,moving:1,settled:1,reunion:3,'gate-out':2,'care-change':4,'care-recovery':5,'companion-shared-home':1,neutered:4,'neuter-recovered':5,'illness-onset':4,'illness-worsening':4,'vet-visit':4,'illness-recovered':5,'companion-close':5,'companion-parting':4,'litter-born':4,death:4};
export function visualFor(s,event=null){const day=event?.day??s.day,phase=visualPhase(s,day),look=lookOf(s);if(!look)return {phase,missing:true,species:s.species||'dog',breed:s.breed,signature:`missing:${s.breed}:${phase}`};const eventId=event?.id||(!s.alive?'death':s.medical?.episode?'illness-onset':s.clinical?.active?(['recovery','rehabilitation'].includes(s.clinical.active.stage)?'surgery-performed':'clinical-symptom'):s.log.slice().reverse().find(e=>e.id in SCENE_IDS&&s.day-e.day<=5)?.id);let sceneIndex=SCENE_IDS[eventId];if(['death','illness-onset','illness-worsening','vet-visit','companion-parting'].includes(eventId)&&s.home==='street')sceneIndex=s.world==='rain'?2:5;const scene=sceneIndex==null?null:{url:'assets/events-atlas.png',columns:3,rows:2,x:sceneIndex%3*50,y:Math.floor(sceneIndex/3)*100,alt:'해당 사건의 환경을 표현한 1인칭 참고 장면'};const detailedMissing=['eyes-open','first-steps','adolescent'].includes(phase);const stage=phase==='newborn'?0:phase==='puppy'||phase==='adolescent'?1:phase==='adult'?2:phase==='senior'?3:0;const portrait=detailedMissing?null:{url:`assets/${look.atlas}`,columns:4,rows:3,x:stage*100/3,y:look.row*50,look:look.id,stage,alt:`${s.breed} · ${look.label} · ${PHASE_NAMES[phase]} 제작 이미지`};return {species:s.species||'dog',breed:s.breed,look:look.id,features:look.label,phase,environment:s.worldModel.context.label,situation:eventId||'daily',portrait,scene,missing:detailedMissing,fallback:'breed-stage-diagram',signature:`${look.id}:${phase}:${s.worldModel.context.id}:${s.areaId}:${s.caregiverId||''}:${eventId||'daily'}:${s.medical?.episode?.stage||''}:${s.alive}`};}
export function diagramSvg(s,phase=visualPhase(s)){const look=lookOf(s),id=look?.id;const color={gold:'#bf945d','black-white':'#383d3b',chocolate:'#795044',jindo:'#e8ddc7',labrador:'#d4b57a',poodle:'#c99667',shiba:'#b77a43',pariah:'#b98b5c',terrier:'#9d7956',shepherd:'#8b693f','small-mix':'#c3a47c',husky:'#8c9696'}[id]||'#bba98d';const ears=['black-white','jindo','shiba','pariah','shepherd','husky'].includes(id)?'<path d="M90 94 80 45 115 75M160 75 194 45 183 103"/>':'<ellipse cx="86" cy="110" rx="18" ry="35"/><ellipse cx="186" cy="110" rx="18" ry="35"/>';const standing=phase!=='newborn'&&phase!=='eyes-open';return `<svg xmlns="http://www.w3.org/2000/svg" width="320" height="280" viewBox="0 0 280 240"><rect width="280" height="240" rx="18" fill="#eee7d9"/><ellipse cx="140" cy="210" rx="104" ry="10" fill="#d7d4c7"/><g fill="${color}" stroke="#665b4b" stroke-width="3">${standing?'<ellipse cx="149" cy="153" rx="65" ry="39"/><path d="M105 170v35h19v-35M176 170v35h19v-35"/>':'<ellipse cx="149" cy="176" rx="73" ry="30"/>'}${ears}<ellipse cx="136" cy="111" rx="49" ry="44"/></g><ellipse cx="136" cy="129" rx="29" ry="20" fill="#eee3d0"/><path d="M129 124q7-7 14 0l-7 7z" fill="#3b3731"/>${phase==='newborn'?'<path d="m110 105 12 3m30 0 12-3" stroke="#443f35" stroke-width="3"/>':'<circle cx="115" cy="105" r="4" fill="#34362f"/><circle cx="157" cy="105" r="4" fill="#34362f"/>'}<path d="M136 131v7m-7 0q7 6 14 0" fill="none" stroke="#655749" stroke-width="2"/><path d="M126 79q10-9 20 0l-5 32h-9z" fill="#f1e6d5" opacity=".8"/></svg>`;}
